import React, {useContext, useState} from "react";
import noteContext from "../context/notes/noteContext";

const AddNote = () => {
    const context = useContext(noteContext);
    const {addNote } = context;
    const [note,setNote] = useState({title:"", description:"", tag:""})
    
    const handleClick = (e) => {
      e.preventDefault();
      console.log("Adding note:", note);
      
      // Validate that required fields are not empty
      if (note.title.length > 0 && note.description.length > 0) {
        addNote(note.title, note.description, note.tag || "default");
        // Clear the form after successful submission
        setNote({title:"", description:"", tag:""});
      } else {
        alert("Title and Description are required and must be at least 1 character long");
      }
    }
    
    const onChange = (e) => {
      setNote({...note, [e.target.name]: e.target.value})
    }

  return (
    <div className="container">
      <h1>Add a Note</h1>
      <form>
        <div className="mb-3">
          <label htmlFor="title" className="form-label">
            Title
          </label>
          <input
            type="text"
            className="form-control"
            id="title"
            name="title"
            value={note.title}
            aria-describedby="emailHelp"
            onChange={onChange}
            minLength={1}
            required
          />
        </div>
        <div className="mb-3">
          <label htmlFor="description" className="form-label">
            Description
          </label>
          <input
            type="text"
            className="form-control"
            id="description"
            name="description"
            value={note.description}
            onChange={onChange}
            minLength={1}
            required
          />
        </div>
        <div className="mb-3">
          <label htmlFor="tag" className="form-label">
            Tag
          </label>
          <input
            type="text"
            className="form-control"
            id="tag"
            name="tag"
            value={note.tag}
            onChange={onChange}
            placeholder="Optional"
          />
        </div>
        
        <button 
          type="submit" 
          className="btn btn-primary" 
          onClick={handleClick}
          disabled={note.title.length === 0 || note.description.length === 0}
        >
          Add Note
        </button>
      </form>
    </div>
  );
};

export default AddNote;
